import json, time, urllib.request, urllib.error, sys
BASE="http://localhost:8080"
tok=None
log=open("/tmp/recon/http.log","a")
def get_token():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(BASE+"/token",method="POST",data=b""))
            tok=json.load(r)["token"]; log.write(f"TOKEN {tok}\n"); return
        except urllib.error.HTTPError as e:
            body=e.read(); log.write(f"TOKEN ERR {e.code} {dict(e.headers)} {body[:200]}\n")
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(path):
    if tok is None: get_token()
    attempt=0
    while True:
        attempt+=1
        req=urllib.request.Request(BASE+path,headers={"Authorization":f"Bearer {tok}"})
        try:
            r=urllib.request.urlopen(req,timeout=30)
            body=r.read()
            try: return 200,json.loads(body)
            except Exception:
                log.write(f"{path} BADJSON {body[:300]!r}\n"); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body=e.read()
            log.write(f"{path} {e.code} {dict(e.headers)} {body[:300]!r}\n")
            if e.code==401: get_token(); continue
            if e.code==429:
                time.sleep(float(e.headers.get("Retry-After") or 1)); continue
            if e.code==404: return 404,body
            time.sleep(min(2**min(attempt,4)*0.25,5)); continue
        except Exception as e:
            log.write(f"{path} EXC {e!r}\n"); time.sleep(1); continue

pages={}
path="/orders?page=1"
while path:
    st,d=get(path)
    pages[d["page"]]=d
    print("page",d["page"],d["total_pages"],len(d["items"]),d["next"],file=sys.stderr)
    path=d["next"]
json.dump(pages,open("/tmp/recon/pages.json","w"))
cust_ids=sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs={}
for c in cust_ids:
    st,d=get(f"/customers/{c}")
    custs[c]=d if st==200 else None
json.dump(custs,open("/tmp/recon/customers.json","w"))
print("done",len(pages),len(custs),file=sys.stderr)
EOF
cd /tmp/recon && python3 -I fetch.py 2>&1 | tail -40

